def main():
    assert set(P.keys()) == set(BATCH), (set(P.keys()) ^ set(BATCH))
    os.makedirs(OUT, exist_ok=True)
    for cid in BATCH:
        d = P[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"],
               "basis": d["basis"], "confidence": d["confidence"], "trigger": d["trigger"]}
        assert rec["case_id"] and rec["prediction_text"] and rec["basis"]
        assert isinstance(rec["confidence"], float) and 0.0 <= rec["confidence"] <= 1.0
        t = rec["trigger"]
        assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}
        assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed"))
        with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    written = sorted(fn[:-5] for fn in os.listdir(OUT) if fn[:-5] in BATCH and fn.endswith(".json"))
    assert written == sorted(BATCH), written
    print("written:", len(written))
    print("changed_main:", sum(P[c]["trigger"]["changed_main"] for c in BATCH))
    print("reserve_used:", sum(P[c]["trigger"]["reserve_used"] for c in BATCH))
    print("disputed:", sum(P[c]["trigger"]["disputed"] for c in BATCH))

if __name__ == "__main__":
    main()
